// Generated by scripts/build-okf.mjs from knowledge/*.md. Do not edit by hand.
export const OKF_SOURCES: Record<string, string> = {
  "accounts-and-roles.md":
    "---\nid: accounts-and-roles\ntype: policy\ntitle: Accounts and roles\ndescription: How to create and manage a CareBridge account and how staff roles are assigned.\nowner: Front desk\ntags: [accounts, roles, sign-in]\naliases: [create an account, sign in with google, cannot sign in, update my profile, family shared account]\ntimestamp: 2026-10-07\n---\n\n# Accounts and roles\n\n## Creating an account\n\nSign up in the CareBridge app with an email and password, or use **Sign in with Google** on the login page. Every new account is a patient account.\n\n## One person, one account\n\nEach person needs their own account. Family members cannot share one account, and each patient books from their own account.\n\n## Your profile\n\nOpen **My Profile** to update details such as your phone number, address, allergies, and emergency contact.\n\n## Roles\n\nThere are three roles:\n\n- **Patient**: book and manage appointments, join the waitlist, and see your prescriptions and bills.\n- **Doctor**: see their schedule and their own patients' records, and complete consultations.\n- **Receptionist**: confirm, reschedule, and cancel appointments, handle billing, and follow up on missed visits.\n\nDoctor and receptionist roles are assigned by reception. You cannot change your own role.\n\n## Help with your account\n\n- If you cannot sign in, contact reception on +880 1711-000000 (Saturday to Thursday, 9:00 AM to 5:00 PM).\n- To delete your account, contact reception.\n",
  "booking-rules.md":
    "---\nid: booking-rules\ntype: policy\ntitle: Booking rules\ndescription: How to book an appointment, what is needed, and how confirmation works.\nowner: Front desk\ntags: [booking, appointments]\naliases: [book an appointment, how to book, make a booking, is my booking confirmed, walk in appointment]\ntimestamp: 2026-10-07\n---\n\n# Booking rules\n\n## How to book\n\nOpen **Book Appointment** in the app. Choose a doctor, a date, and a time slot, and enter a short reason for the visit. The assistant can also prepare a booking card. Nothing is booked until you press **Confirm**.\n\n## Rules\n\n- You can only book one of the doctor's working days and one of their listed time slots.\n- A slot that is already booked cannot be chosen. You can join the waitlist instead.\n- Each patient books from their own account. Family members need their own accounts.\n- You can book any future working day. There is no limit on how far ahead you book.\n\n## Status\n\n- **Requested**: reception has not confirmed the booking yet. Reception usually confirms it on the same or the next working day.\n- **Confirmed**: shown in My Appointments. You get a reminder within the 24 hours before the visit.\n- **Completed**: the consultation has taken place.\n\n## Walk-ins\n\nWalk-in patients are seen only if a slot is free. Booking in the app is preferred.\n\n## On the day\n\n- Bring photo ID, previous prescriptions, and recent test reports.\n- If you arrive more than 15 minutes late, you may need to reschedule.\n",
  "cancellation-policy.md":
    "---\nid: cancellation-policy\ntype: policy\ntitle: Cancellation policy\ndescription: How and when a patient can cancel an appointment and whether a fee applies.\nowner: Front desk\ntags: [booking, cancellation]\naliases: [cancel appointment, cancellation fee, how do i cancel, cancel my booking]\ntimestamp: 2026-10-07\n---\n\n# Cancellation policy\n\n## How to cancel\n\nOpen **My Appointments** in the app and cancel the appointment. You can also ask the assistant. It prepares a cancellation card, and nothing changes until you press **Confirm** on that card.\n\n## Which appointments can be cancelled\n\n- Only appointments with status **requested** or **confirmed** can be cancelled.\n- Completed appointments cannot be cancelled. Book a new follow-up appointment instead.\n- Once cancelled, an appointment cannot be restored. Book again if you change your mind.\n\n## Fees\n\nThere is no cancellation fee, and there is no minimum notice period. You can cancel at any time before the visit. Please cancel as early as you can so the slot can go to another patient.\n\n## What happens to the freed slot\n\nWhen you cancel, the slot is offered automatically to the next patient on the waitlist for that doctor and day.\n\n## Cancelling for someone else\n\nEach patient cancels from their own account. Reception staff can also cancel an appointment for you. Call +880 1711-000000 during opening hours.\n",
  "consultation-fees.md":
    "---\nid: consultation-fees\ntype: policy\ntitle: Consultation fees\ndescription: How consultation fees are set and where to see a doctor's fee.\nowner: Clinic manager\ntags: [billing, fees]\naliases: [how much does it cost, consultation fee, doctor fee, why are fees different]\ntimestamp: 2026-10-07\n---\n\n# Consultation fees\n\n## How fees are set\n\nEach doctor has their own consultation fee. Senior consultants charge more.\n\n## Where to see a fee\n\n- The doctor list in **Book Appointment** shows each doctor's fee, specialization, and working days.\n- The booking summary shows the fee before you confirm.\n- The assistant can look up a doctor's current fee for you.\n\nAlways check the current fee in the app. The fee shown there is the one that applies.\n\n## Your bill\n\n- Reception creates your bill after the visit.\n- The bill total is built from the items on it, so it may include more than the consultation fee. Reception explains any extra item on request.\n- You pay in cash at reception after the visit. Nothing is paid in advance.\n",
  "emergency-guidance.md":
    "---\nid: emergency-guidance\ntype: guidance\ntitle: Emergency guidance\ndescription: What to do in a medical emergency and why the clinic assistant cannot help with one.\nowner: Medical director\ntags: [emergency, safety, urgent]\naliases: [is this an emergency, call an ambulance, chest pain now, i cannot breathe, i want to hurt myself]\ntimestamp: 2026-10-07\n---\n\n# Emergency guidance\n\nIf you have chest pain, trouble breathing, heavy bleeding, signs of a stroke (face drooping, arm weakness, slurred speech), or thoughts of harming yourself, call 999 immediately. This assistant cannot handle emergencies and cannot send help. Do not wait for a reply in the app.\n\n## The clinic is not an emergency service\n\nCareBridge Clinic runs booked outpatient appointments. For anything sudden or severe, call 999 or go to the nearest hospital emergency department.\n\n## When it is urgent but not an emergency\n\n- Contact reception on +880 1711-000000 during opening hours (Saturday to Thursday, 9:00 AM to 5:00 PM).\n- If you have side effects from a medicine, contact the clinic or your doctor. If they are severe, call 999.\n- Do not use a waitlist or a future booking for a problem that needs care today.\n\n## What the assistant can do\n\nThe assistant gives general information only. It does not diagnose, and it never tells you which medicine or dose to take.\n",
  "medical-records-access.md":
    "---\nid: medical-records-access\ntype: policy\ntitle: Medical records and test results\ndescription: Which of your medical records you can see in the app and how test results are handled.\nowner: Medical director\ntags: [records, test-results, prescriptions]\naliases: [see my medical records, my test results, lab report, view my history]\ntimestamp: 2026-10-07\n---\n\n# Medical records and test results\n\n## What you can see in the app\n\n- **My Appointments**: your past and upcoming visits and their status.\n- **My Prescriptions**: the diagnosis, medicines, and doctor's notes from each completed visit.\n- **Bills**: your bills and whether they are paid.\n- **My Profile**: your contact details, allergies, and emergency contact.\n\nThe assistant can also look these up for you. It only sees your own records.\n\n## Who else can see them\n\nYour doctor sees the records of their own patients. Reception staff can see all records to run the clinic.\n\n## Test results\n\nThe app does not store test results or lab reports. Collect your reports from the lab that did the test, and bring them to your next visit so your doctor can review them.\n\n## Corrections and copies\n\n- To report an error in a prescription or record, contact reception.\n- To get a printed copy of your records or an invoice, ask reception.\n",
  "no-show-policy.md":
    "---\nid: no-show-policy\ntype: policy\ntitle: No-show policy\ndescription: What counts as a missed appointment and what happens afterwards.\nowner: Front desk\ntags: [booking, no-show]\naliases: [missed my appointment, what is a no-show, i did not show up, missed visit]\ntimestamp: 2026-10-07\n---\n\n# No-show policy\n\n## What counts as a no-show\n\nA **confirmed** appointment that has not been completed 1 hour after its start time is flagged as a possible no-show.\n\n## What happens next\n\n- Reception reviews each possible no-show and records a note.\n- Reception may contact you to rebook.\n- You may receive an email inviting you to book again, unless you have opted out of campaign emails.\n\n## Avoiding a no-show\n\n- If you cannot come, cancel in **My Appointments** as early as you can. There is no cancellation fee, and the slot can go to a patient on the waitlist.\n- If you arrive more than 15 minutes late, you may need to reschedule.\n- Check that your booking is **confirmed**. Reminders are sent only for confirmed appointments.\n\n## Rebooking\n\nBook a new appointment in the app, or call reception on +880 1711-000000.\n\nThere is no fee for a missed appointment, and a missed visit does not stop you from booking again.\n",
  "opening-hours.md":
    "---\nid: opening-hours\ntype: policy\ntitle: Opening hours and contact\ndescription: When the clinic is open, where it is, and how to reach reception.\nowner: Clinic manager\ntags: [clinic, hours, contact]\naliases: [opening hours, are you open friday, clinic address, clinic phone number, when do you open]\ntimestamp: 2026-10-07\n---\n\n# Opening hours and contact\n\n## Hours\n\n- **Saturday to Thursday:** 9:00 AM to 5:00 PM (Dhaka time).\n- **Friday and public holidays:** closed.\n\nEach doctor works on set days and times within these hours. The doctor list in **Book Appointment** shows each doctor's working days, and only their listed slots can be booked.\n\n## Contact\n\n- **Phone:** +880 1711-000000 (reception, during opening hours)\n- **Address:** House 27, Road 9/A, Dhanmondi, Dhaka 1209\n\nReception staff speak Bangla and English.\n\n## Getting here\n\n- Only limited street parking is available.\n- There is a wheelchair ramp and a lift at the entrance.\n\n## Outside opening hours\n\nYou can still book, cancel, and reschedule in the app at any time. Reception confirms new bookings on the next working day. For emergencies, call 999 or go to the nearest hospital emergency department.\n\nHours can change around public holidays and during Ramadan. Call reception to check before you travel.\n",
  "payment-methods.md":
    "---\nid: payment-methods\ntype: policy\ntitle: Payment methods\ndescription: How and when to pay a clinic bill and which payment methods are accepted.\nowner: Clinic manager\ntags: [billing, payment]\naliases: [how do i pay, can i pay by card, mobile banking payment, pay my bill, accepted payment methods]\ntimestamp: 2026-10-07\n---\n\n# Payment methods\n\n## When you pay\n\nYou pay after your visit, not in advance. Reception creates your bill once the consultation is completed. There is one bill per appointment.\n\n## Where you pay\n\nPay at reception after the visit. You cannot pay inside the app.\n\n## Accepted methods\n\n- **Cash**: available.\n- **Card**: not available at present.\n- **Mobile banking**: not available at present.\n\nPlease pay in cash until card and mobile banking payments become available.\n\n## Bill status\n\n- **Unpaid**: the bill has not been paid yet.\n- **Paid**: reception has recorded your payment.\n\nYou can see your bills in the app, and the assistant can show them to you. Ask reception for a printed invoice.\n\n## Insurance\n\nThe clinic does not accept insurance at present. Pay the bill in cash and ask reception for a printed invoice if your insurer needs one.\n",
  "prescription-renewal.md":
    "---\nid: prescription-renewal\ntype: policy\ntitle: Prescription renewal\ndescription: How to get a repeat prescription and where to find your prescriptions.\nowner: Medical director\ntags: [prescriptions, refill]\naliases: [renew my prescription, prescription refill, repeat prescription, where is my prescription]\ntimestamp: 2026-10-07\n---\n\n# Prescription renewal\n\n## Getting a refill\n\nTo renew a prescription, book a follow-up appointment with your doctor. Prescriptions are only written during a consultation, so a doctor cannot renew one without a visit.\n\n## Where to find your prescriptions\n\n- Open **My Prescriptions** in the app.\n- A prescription appears once the appointment is completed. The doctor writes it at the end of the consultation.\n- Each appointment has one prescription.\n\nA prescription shows the date, the doctor, the diagnosis, each medicine with its instructions, and the doctor's notes.\n\n## Follow-up dates\n\nYour doctor may set a follow-up date. If it passes without a visit, the clinic may email you a reminder to book, unless you have opted out of campaign emails.\n\n## What the assistant cannot do\n\n- The assistant cannot write, renew, or change a prescription. Only your doctor can.\n- It will not tell you which medicine or dose to take.\n\n## Problems\n\n- To report an error on a prescription, contact reception.\n- For side effects, contact the clinic or your doctor. In an emergency, call 999.\n",
  "privacy.md":
    "---\nid: privacy\ntype: policy\ntitle: Privacy\ndescription: Who can see your information in CareBridge and how your data is used.\nowner: Clinic manager\ntags: [privacy, data, security]\naliases: [is my data private, privacy policy, are my chats private, delete my data]\ntimestamp: 2026-10-07\n---\n\n# Privacy\n\n## Who can see your information\n\n- **You** see only your own appointments, prescriptions, bills, and profile.\n- **Doctors** see the records of their own patients.\n- **Reception staff** can see all records to run the clinic.\n\nThese limits are enforced by the database for every screen and for the assistant. The assistant can only read what you are allowed to see.\n\n## Booking privacy\n\nWhen you look at free slots, the app shows which times are taken but never who booked them.\n\n## The assistant\n\n- Your chats with the assistant are private to your account.\n- The assistant never makes a change on its own. You must press **Confirm** on its proposal card.\n- Its general knowledge comes from anonymised records. It never names other patients.\n\n## Emails\n\nThe clinic uses your email address for appointment reminders and, unless you opt out, for campaign emails. See the reminders and email preferences policy.\n\n## Deleting your account\n\nContact reception on +880 1711-000000 to delete your account. Your medical and billing records may be kept after your account is closed, because the clinic needs them for its records. Ask reception for details.\n",
  "refund-policy.md":
    "---\nid: refund-policy\ntype: policy\ntitle: Refund policy\ndescription: Whether the clinic takes advance payments and how billing problems are handled.\nowner: Clinic manager\ntags: [billing, refund]\naliases: [can i get a refund, refund my payment, money back, do i pay in advance]\ntimestamp: 2026-10-07\n---\n\n# Refund policy\n\n## No advance payment\n\nYou do not pay when you book. Payment is made at reception after your visit, once your bill has been created. Because nothing is paid in advance, cancelling or rescheduling never costs you anything and there is nothing to refund.\n\n## No refund process\n\nThe clinic does not have a refund process for completed consultations.\n\n## If you think your bill is wrong\n\n- Check your bill in the app. The assistant can show it to you.\n- Contact reception on +880 1711-000000 during opening hours, or ask at the front desk on your next visit.\n- Do not pay a bill you believe is wrong until reception has checked it.\n- If you paid twice or were charged in error, reception checks the bill and returns the extra amount in cash.\n",
  "reminder-and-email-preferences.md":
    "---\nid: reminder-and-email-preferences\ntype: policy\ntitle: Reminders and email preferences\ndescription: Which reminders and emails the clinic sends and how to stop them.\nowner: Front desk\ntags: [notifications, email, reminders]\naliases: [appointment reminder, stop emails, unsubscribe from emails, sms reminders, did not get reminder]\ntimestamp: 2026-10-07\n---\n\n# Reminders and email preferences\n\n## Appointment reminders\n\n- A reminder is sent within the 24 hours before a **confirmed** appointment. Requested bookings do not get reminders.\n- Reminders appear under the bell icon in the app.\n- If you have an email address on your profile, the reminder is also emailed to you.\n- The clinic does not send SMS reminders.\n\nEmails are not sent between 10:00 PM and 8:00 AM (Dhaka time). An email due overnight arrives after 8:00 AM.\n\n## Other notifications\n\nThe bell icon also shows waitlist offers and expired offers.\n\n## Campaign emails\n\nThe clinic may email invitations, for example when a check-up or follow-up is due or after a missed visit. You get at most one campaign email every 7 days.\n\n## Stopping emails\n\n- Every campaign email has an **Unsubscribe** link. It stops campaign emails, and appointment reminders still arrive.\n- On the same page you can tick **Also stop appointment reminder emails** to stop all emails.\n- Reception can also record your choice. Contact reception to change it later.\n\nIn-app notifications under the bell icon continue either way.\n",
  "rescheduling-policy.md":
    "---\nid: rescheduling-policy\ntype: policy\ntitle: Rescheduling policy\ndescription: The rules for moving an existing appointment to a new date or time slot.\nowner: Front desk\ntags: [booking, reschedule]\naliases: [reschedule appointment, change my appointment time, move my booking, change appointment date]\ntimestamp: 2026-10-07\n---\n\n# Rescheduling policy\n\n## How to reschedule\n\nOpen **My Appointments** and choose reschedule, or ask the assistant. The assistant prepares a card, and nothing changes until you press **Confirm**.\n\n## Rules\n\n- Only **requested** or **confirmed** appointments can be rescheduled.\n- The new date cannot be in the past.\n- You stay with the same doctor. To see a different doctor, cancel and book a new appointment.\n- The new day must be one of the doctor's working days, and the new time must be one of the doctor's listed slots.\n- The new slot must be free. A slot that someone else has booked cannot be chosen.\n\n## After you reschedule\n\nWhen you reschedule, the appointment goes back to **requested**. Reception then confirms it again. If reception moves the appointment for you, it stays **confirmed**.\n\nYour old slot is then offered to the next patient on the waitlist.\n\n## Completed visits\n\nCompleted appointments cannot be rescheduled. Book a follow-up appointment instead.\n\nThere is no fee for rescheduling, and there is no limit on how many times you reschedule.\n",
  "waitlist.md":
    "---\nid: waitlist\ntype: policy\ntitle: Waitlist\ndescription: How the waitlist works, how offers are made, and how long you have to accept.\nowner: Front desk\ntags: [booking, waitlist]\naliases: [join the waitlist, waitlist offer, offer expired, leave the waitlist, slot is full]\ntimestamp: 2026-10-07\n---\n\n# Waitlist\n\n## When to use it\n\nJoin the waitlist when the day or slot you want with a doctor is fully booked. If the slot you want is free, book it directly instead.\n\n## Rules for joining\n\n- Choose today or a future date on one of the doctor's working days.\n- You can name one taken slot, or leave the slot open to accept any time that day.\n- You can have one open waitlist entry per doctor and day.\n\n## Offers\n\nWhen a matching appointment is cancelled or moved, the slot is offered to the next waiting patient. Patients who asked for that exact slot come first, then the earliest to join.\n\n- You get a notification under the bell icon, and the offer appears in **My Appointments**.\n- You have **120 minutes** to accept the offer.\n- An accepted offer becomes a booking with status **requested**, which reception then confirms.\n- If you decline, or do not accept in time, the slot passes to the next patient. You stay on the waitlist for other slots that day.\n\n## Leaving\n\nYou can leave the waitlist at any time from My Appointments. Entries for dates that have passed close automatically.\n",
};
